const START={calculator_failed:'The calculator could not start. Please refresh the page.'};const row=(m)=>`Appliance ${Number(m[1])+1}: `;const PATTERNS=[[/^(protected|lifeline)_max_(\d+)_units$/,(m)=>`${cap(m[1])} tariff applies only up to ${m[2]} units a month.${m[1]=='protected'?' Above that the unprotected rate applies.':''}`],[/^history_needs_(\d+)_months$/,(m)=>`Enter units for each of the last ${m[1]} months.`],[/^history_(\d+)_invalid$/,(m)=>`Month ${m[1]}: enter the units as a number (0 or more).`],[/^load_(\d+)_start_below_run$/,(m)=>`${row(m)}starting watts cannot be lower than running watts.`],[/^load_(\d+)_watts_required$/,(m)=>`${row(m)}enter its watts.`],[/^load_(\d+)_hours_invalid$/,(m)=>`${row(m)}hours per day must be a number from 0 to 24.`],[/^load_(\d+)_start_invalid$/,(m)=>`${row(m)}enter its starting watts as a number (0 or more).`],[/^load_(\d+)_qty_invalid$/,(m)=>`${row(m)}enter how many as a whole number (0 or more).`],[/^(?:load|appliance)_(\d+)_(?:\w+_)?invalid$/,(m)=>`${row(m)}enter its watts as a number (0 or more).`],[/^load_(\d+)_(?:length_(?=r))?(.+)$/,(m,c)=>row(m)+errorMessage(m[2],{...c,fields:[]})],[/^(\w+)_required$/,(m,c,f)=>`Enter ${f(m[1])}${eg(c,m[1])}.`],[/^(\w+)_invalid$/,(m,c,f)=>(fld(c,m[1]).options?`Choose ${f(m[1])} from the list.`:`Enter ${f(m[1])} as a plain number${eg(c,m[1])||', for example 12 or 1500'}.`)],[/^(\w+)_must_be_positive$/,(m,c,f)=>`${cap(f(m[1]))} must be greater than 0${eg(c,m[1])}.`],[/^(\w+)_too_(small|large)$/,(m,c,f)=>cap(f(m[1]))+(c.limit==null?` is too ${m[2]}. Check the number and its unit.`:m[2]=='small'?` must be at least ${lim(c)}.`:` must be ${lim(c)} or less.`)],];const cap=(s)=>s.charAt(0).toUpperCase()+s.slice(1);const fld=(c,key)=>c.fields?.find((x)=>x.name===key)||{};const lim=(c)=>c.limit.toLocaleString('en-US');const eg=(c,key)=>{const d=fld(c,key).default;return d !=null&&typeof d !='object'&&!fld(c,key).options?`, for example ${d}`:'';};export const NOTICES={solar_above_sanctioned:1,low_confidence:'price_low_confidence',over_cable_rating:'cable_over_current_rating',ampacity_checked:'ampacity_not_checked_aluminium',protected_lost:'ac_protected_lost',ac_above_sanctioned:1,usage_both:1,typical_used:1,per_unit_hidden:1,battery_unknown:1,high_c_rate:1};export function noticeCode(out){const above=Object.keys(out).filter((k)=>k.endsWith('above_standard_sizes')&&out[k]===true);if(above.length)return above.every((k)=>k==='generator_above_standard_sizes'||'recommended_kva' in out)?'generator_above_standard_sizes':'above_standard_sizes';for(const k in NOTICES)if(out[k]===(k !='ampacity_checked'))return NOTICES[k]===1?k:NOTICES[k];return '';}
export function errorMessage(code,c={}){const t=c.texts?.[code]||START[code];if(t)return t;const f=(key)=>{const x=fld(c,key);return(x.label||key.replace(/_/g,' ')).replace(/^[A-Z](?=[a-z])/,(s)=>s.toLowerCase())+(x.unit?` (${x.unit})`:'');};for(const[re,make]of PATTERNS){const m=code.match(re);if(m)return make(m,c,f);}
return 'Something went wrong with this calculation. Please check your inputs.';}
